insert into public.questionnaire_templates (id, name, description, category, active, created_at, required_for_intake) values ('991646ab-f1ec-4e1b-9356-9f0e52690af1', 'SF-36 健康調查簡表', '台灣/IQOLA 標準中文版，共36道子題，病人自填。八大構面各自轉換為0-100分：（構面實際得分－可能最低得分）÷分數範圍×100，非簡單加總。', 'other', 'true', '2026-07-27 02:47:17.089665+00', 'true') on conflict do nothing;
