insert into public.health_education_kb (id, topic, content, active, sort_order, created_at, updated_at, category, pdf_url, video_url) values ('bde17fc7-67bd-4ec5-88ef-0cb32c966b1a', '傷口/疤痕會癢怎麼辦', '蟹足腫在增生期常見搔癢，可用醫師開立的止癢藥膏，避免抓搔以免刺激增生。若持續劇癢或合併紅腫熱痛，請於下次回診或提前聯繫診間。', 'true', '1', '2026-07-26 15:07:59.994468+00', '2026-07-26 15:07:59.994468+00', '疤痕護理', 'https://sijhih.cgh.org.tw/rwd102/store/F1/3.%E6%83%B1%E4%BA%BA%E7%9A%84%E3%80%8C%E8%9F%B9%E3%80%8D%E8%B6%B3%E8%85%AB%E7%9C%9F%E7%9A%84%E5%8F%AF%E4%BB%A5%E6%A0%B9%E6%B2%BB%EF%BC%9F.pdf', NULL) on conflict do nothing;
insert into public.health_education_kb (id, topic, content, active, sort_order, created_at, updated_at, category, pdf_url, video_url) values ('157b1b5e-366c-46a1-98fb-b028db045c50', '放射治療會不會痛？', '放射治療本身不會痛，過程中不會有針扎或灼熱的感覺，通常幾分鐘就結束，照射時只要放鬆躺好即可。
insert into public.health_education_kb (id, topic, content, active, sort_order, created_at, updated_at, category, pdf_url, video_url) values ('c18e13aa-c3ba-4158-a362-8029b4d99537', '疤痕可以曬太陽嗎？需要防曬嗎？', '新生的疤痕對紫外線比較敏感，曬太陽容易造成色素沉澱，讓疤痕看起來更明顯。
insert into public.health_education_kb (id, topic, content, active, sort_order, created_at, updated_at, category, pdf_url, video_url) values ('a93d2c91-1cc8-418e-8597-203c5a028f12', '傷口照顧與飲食注意事項', '傷口癒合期間請維持均衡飲食。以下忌口與建議依主治醫師確認：
insert into public.health_education_kb (id, topic, content, active, sort_order, created_at, updated_at, category, pdf_url, video_url) values ('278aaf1b-0331-45f8-aa86-4a8059f4cb4c', '蟹足腫治療術後注意事項', '1. 暫勿運動，以防拉扯傷口。
insert into public.health_education_kb (id, topic, content, active, sort_order, created_at, updated_at, category, pdf_url, video_url) values ('42dced07-45ee-4ff7-8fa4-bd02de8e25f3', '類固醇注射會不會痛？要打幾次？', '病灶內注射時會有短暫的脹痛或刺痛感，通常幾分鐘內就緩解，注射後當天該部位可能會比較痠，若需要可服止痛藥。
insert into public.health_education_kb (id, topic, content, active, sort_order, created_at, updated_at, category, pdf_url, video_url) values ('ef70c53c-1815-47f9-af8d-c0187d2e8cd3', '疤痕要多久才會變淡、變平？', '蟹足腫的疤痕成熟需要時間，一般在治療後數個月才會逐漸變軟、變淡，完全穩定可能需要一年以上。
insert into public.health_education_kb (id, topic, content, active, sort_order, created_at, updated_at, category, pdf_url, video_url) values ('1817cb54-3293-48f2-ab28-b20653c02c10', '手術後傷口多久可以碰水、洗澡？', '一般原則是前幾天避免直接淋水，可以擦澡並避開傷口；可以等拆線後、傷口完全癒合再恢復正常淋浴，但若有例外，可以詢問主治醫師。
insert into public.health_education_kb (id, topic, content, active, sort_order, created_at, updated_at, category, pdf_url, video_url) values ('143456fc-5a0a-4371-befb-743e53af4c4a', '矽膠片要戴多久', '一般建議每日配戴 18-23 小時，持續數個月，實際天數與部位請以主治醫師指示為準，勿自行停用。', 'true', '2', '2026-07-26 15:07:59.994468+00', '2026-08-07 18:25:28.119+00', '疤痕護理', 'https://sijhih.cgh.org.tw/rwd102/store/F1/3.%E6%83%B1%E4%BA%BA%E7%9A%84%E3%80%8C%E8%9F%B9%E3%80%8D%E8%B6%B3%E8%85%AB%E7%9C%9F%E7%9A%84%E5%8F%AF%E4%BB%A5%E6%A0%B9%E6%B2%BB%EF%BC%9F.pdf', NULL) on conflict do nothing;
insert into public.health_education_kb (id, topic, content, active, sort_order, created_at, updated_at, category, pdf_url, video_url) values ('bec4d3eb-83f2-4170-aae6-ac1991032909', '放射治療為什麼要連續做？可以改天嗎？', '手術切除後的放射治療是為了抑制疤痕再度增生，需要在傷口癒合的關鍵期完成，通常在手術後隔天開始、連續每天一次。
insert into public.health_education_kb (id, topic, content, active, sort_order, created_at, updated_at, category, pdf_url, video_url) values ('879e3f20-7454-483e-8420-535566f0a0d2', '矽膠片使用了會癢、悶熱怎麼辦？', '悶熱、輕微搔癢是常見的，尤其在夏天。可以在皮膚清潔乾爽後再配戴，並依指示定期清洗替換。
insert into public.health_education_kb (id, topic, content, active, sort_order, created_at, updated_at, category, pdf_url, video_url) values ('0015edda-9f69-474f-baa9-489349b252e7', '什麼情況要提前回診？', '出現以下情況請不要等到下次回診，盡快聯繫診間或就醫：
insert into public.health_education_kb (id, topic, content, active, sort_order, created_at, updated_at, category, pdf_url, video_url) values ('9687db1e-64fd-4765-83dc-88235698beda', '什麼時候可以恢復運動？', '傷口癒合期間應避免會拉扯到傷口的動作與劇烈運動，因為張力會刺激疤痕增生，這也是蟹足腫容易長在肩膀、前胸的原因之一。
insert into public.health_education_kb (id, topic, content, active, sort_order, created_at, updated_at, category, pdf_url, video_url) values ('8d311ac5-42ba-43c6-976c-db10b4213df2', '放射治療後照射部位的皮膚要怎麼照顧？', '照射部位的定位劃線不必刻意保留，但也不要用力搓洗擦除，以免弄破皮膚。
insert into public.health_education_kb (id, topic, content, active, sort_order, created_at, updated_at, category, pdf_url, video_url) values ('9c6f6650-2fe3-446d-95c5-0547de52fb09', '蟹足腫會遺傳嗎？', '蟹足腫和體質有關，有家族史的人比較容易發生，這也是收案時會詢問家族史的原因。
insert into public.line_message_templates (key, content, updated_at, updated_by) values ('reminder.visit.lead_days', '0', '2026-07-30 15:12:57.900588+00', '系統設定（省 LINE 額度，2026-07-30）') on conflict do nothing;
